    "body": {
        "id": "http://dbpedia.org/resource/Katherine_Anne_Porter",
        "type": "crm:E21_Person",
        "label": "Katherine Anne Porter",
        "description": "Katherine Anne Porter (May 15, 1890 – September 18, 1980) was an American journalist, essayist, short story writer, novelist, and political activist. Her 1962 novel Ship of Fools was the best-selling novel in America that year, but her short stories received much more critical acclaim."
    },
